/**
 * Stateful entry point for the Analysis bottom-nav tab. Lifecycle wiring, pull-to-refresh, and the
 * loading/error/empty state machine all follow `IndicatorsRoute`/`NewsRoute`'s exact shape --
 * `StockAnalysisScreen` (and its sibling error/empty composables) stay pure data-in, lambdas-out,
 * same as every other tab's Screen. Loading itself is `PulseLoadingIndicator`, same as every other
 * screen in the app -- this tab used to show a static card-shaped skeleton instead, replaced for
 * one consistent loading treatment app-wide.
 *
 * Now carries its own page tabs (Favorites/Stocks/Indices-ETF) -- pinned `PulseTabRow` above the
 * pull-to-refresh area plus a swipeable `HorizontalPager`, same shape `InsightsRoute` already uses
 * and for the same reason: the tabs stay reachable and pulling-to-refresh works regardless of
 * which tab's content is loading/erroring/showing below.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun StockAnalysisRoute(
    scaffoldPadding: PaddingValues,
    onNavigateToDetail: (String) -> Unit,
    viewModel: StockAnalysisViewModel = hiltViewModel()
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val snackbarHostState = remember { SnackbarHostState() }
    val pullRefreshState = rememberPullToRefreshState()
    val lifecycleOwner = LocalLifecycleOwner.current

    // 💡 Same two one-directional effects `InsightsRoute` uses to keep `pagerState` and the
    // ViewModel's `selectedTabIndex` in sync without fighting each other -- see that Route's own
    // comments for why `settledPage` specifically (not `currentPage`) on the swipe-driven effect.
    val pagerState = rememberPagerState(initialPage = uiState.selectedTabIndex) { StockAnalysisTab.entries.size }

    LaunchedEffect(uiState.selectedTabIndex) {
        if (pagerState.currentPage != uiState.selectedTabIndex) {
            pagerState.animateScrollToPage(uiState.selectedTabIndex)
        }
    }

    LaunchedEffect(pagerState.settledPage) {
        if (pagerState.settledPage != uiState.selectedTabIndex) {
            viewModel.onTabSelected(pagerState.settledPage)
        }
    }

    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            when (event) {
                Lifecycle.Event.ON_START -> viewModel.onStart()
                Lifecycle.Event.ON_STOP -> viewModel.onStop()
                else -> {}
            }
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose {
            lifecycleOwner.lifecycle.removeObserver(observer)
        }
    }

    // Soft-error toast -- fires regardless of which state below renders, same as
    // IndicatorsRoute/NewsRoute, so a background refresh failure surfaces even when cached
    // previews are still on screen.
    LaunchedEffect(uiState.error) {
        uiState.error?.message?.let { message ->
            snackbarHostState.showSnackbar(message)
            viewModel.clearError()
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(top = scaffoldPadding.calculateTopPadding())
    ) {
        PulseTabRow(
            tabs = StockAnalysisTab.entries.map { stringResource(id = it.labelRes) },
            selectedTabIndex = uiState.selectedTabIndex,
            onTabSelected = viewModel::onTabSelected,
            highlightedTabIndex = StockAnalysisTab.FAVORITES.ordinal
        )

        Box(modifier = Modifier.fillMaxSize()) {
            PullToRefreshBox(
                isRefreshing = uiState.isRefreshing,
                onRefresh = { viewModel.refresh() },
                state = pullRefreshState,
                indicator = {
                    Indicator(
                        modifier = Modifier.align(Alignment.TopCenter),
                        isRefreshing = uiState.isRefreshing,
                        state = pullRefreshState
                    )
                }
            ) {
                when {
                    // Case A: previews available (from cache or a fresh fetch) -- takes top priority
                    // even mid-refresh, so pull-to-refresh doesn't blank the list while it runs.
                    uiState.previews.isNotEmpty() -> {
                        StockAnalysisScreen(
                            previews = uiState.previews,
                            analyzedAsOf = uiState.analyzedAsOf,
                            isEquityOpen = uiState.isEquityOpen,
                            pagerState = pagerState,
                            favoriteSymbols = uiState.favoriteSymbols,
                            onCardClick = onNavigateToDetail,
                            onToggleFavorite = viewModel::toggleFavorite,
                            getIntradayStream = viewModel::getIntradayStream,
                            scaffoldPadding = PaddingValues(bottom = scaffoldPadding.calculateBottomPadding())
                        )
                    }

                    // Case B: first-ever load, nothing cached yet.
                    uiState.isLoading -> {
                        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                            PulseLoadingIndicator()
                        }
                    }

                    // Case C: no cached previews AND the fetch failed.
                    uiState.error != null -> {
                        StockAnalysisErrorState(
                            error = uiState.error!!,
                            onRetry = { viewModel.refresh() }
                        )
                    }

                    // Case D: genuinely empty -- no previews, not loading, no error (pre-SSO / no
                    // tracked stocks).
                    else -> {
                        StockAnalysisEmptyState()
                    }
                }
            }

            SnackbarHost(
                hostState = snackbarHostState,
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .padding(bottom = scaffoldPadding.calculateBottomPadding())
            )
        }
    }
}
